namespace Fanex.Razorbill.Module.RnGCasino
{
    using System.Web.Mvc;
    using System.Web.Optimization;
    using Fanex.Razorbill.Module.RnGCasino.App_Start;

    /// <summary>
    /// RNG Casino Registration.
    /// </summary>
    public class RnGCasinoRegistration : AreaRegistration
    {
        public override string AreaName
        {
            get 
            { 
                return "RnGCasino"; 
            }
        }

        public override void RegisterArea(AreaRegistrationContext context)
        {     
            RegisterRoutes(context);
            BundleConfig.RegisterBundles(BundleTable.Bundles);
        }

        private void RegisterRoutes(AreaRegistrationContext context)
        {
            context.MapRoute(
                name: this.AreaName + "_Default",
                url: this.AreaName + "/{controller}/{action}/{id}",
                defaults: new { controller = "HandHistory", action = "Index", id = UrlParameter.Optional },
                namespaces: new string[] { "Fanex.Razorbill.Module.RnGCasino.Controllers" }
            );
        }
    }
}
